// Generates the typed API client from backend/openapi.json (P14-T04, ADR-0018), or with `--check`
// verifies that the committed client is up to date: any drift fails CI.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const SPEC = here("../../backend/openapi.json");
const OUT = here("../src/lib/api/schema.d.ts");
const HEADER =
  "// Generated by scripts/api-client.mjs from backend/openapi.json. Do not edit by hand:\n" +
  "// run `npm run api:generate`. CI fails if this file drifts from the specification.\n\n";

const spec = JSON.parse(readFileSync(SPEC, "utf8"));
const generated = (HEADER + astToString(await openapiTS(spec))).replace(/\r\n/g, "\n");

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8").replace(/\r\n/g, "\n");
  } catch {
    // missing file: reported as drift below
  }
  if (current !== generated) {
    console.error("src/lib/api/schema.d.ts is out of date with backend/openapi.json. Run `npm run api:generate`.");
    process.exit(1);
  }
  console.log("API client matches backend/openapi.json");
} else {
  writeFileSync(OUT, generated);
  console.log("wrote src/lib/api/schema.d.ts");
}
